mapper.select:
select t.gun_num,t.gun_num gunNum,t.order_id,t.order_id
orderId,t.accumulated_charging_time,t.accumulated_charging_time
accumulatedChargingTime,t.output_voltage,t.output_voltage outputVoltage,t.soc,t.cpa_id,t.cpa_id
cpaId,t.status_cd,t.status_cd statusCd,t.remark,t.charging_degree,t.charging_degree
chargingDegree,t.inserted_gun,t.inserted_gun insertedGun,t.output_current,t.output_current
outputCurrent,t.remaining_time,t.remaining_time remainingTime,t.gun_line_tem,t.gun_line_tem
gunLineTem,t.back_in_place,t.back_in_place backInPlace,t.batterypack_max_tem,t.batterypack_max_tem
batterypackMaxTem,t.machine_id,t.machine_id machineId,t.pile_num,t.pile_num
pileNum,t.calculated_charging_degree,t.calculated_charging_degree
calculatedChargingDegree,t.hardware_failure,t.hardware_failure
hardwareFailure,t.recharge_amount,t.recharge_amount rechargeAmount,t.create_time,t.create_time
createTime,t.gun_code,t.gun_code gunCode,t.community_id,t.community_id communityId,t.status
from charge_process_analysis t
where 1 =1

    and t.gun_num= #{gunNum}


    and t.order_id= #{orderId}


    and t.accumulated_charging_time= #{accumulatedChargingTime}


    and t.output_voltage= #{outputVoltage}


    and t.soc= #{soc}


    and t.cpa_id= #{cpaId}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.charging_degree= #{chargingDegree}


    and t.inserted_gun= #{insertedGun}


    and t.output_current= #{outputCurrent}


    and t.remaining_time= #{remainingTime}


    and t.gun_line_tem= #{gunLineTem}


    and t.back_in_place= #{backInPlace}


    and t.batterypack_max_tem= #{batterypackMaxTem}


    and t.machine_id= #{machineId}


    and t.pile_num= #{pileNum}


    and t.calculated_charging_degree= #{calculatedChargingDegree}


    and t.hardware_failure= #{hardwareFailure}


    and t.recharge_amount= #{rechargeAmount}


    and t.create_time= #{createTime}


    and t.gun_code= #{gunCode}


    and t.community_id= #{communityId}


    and t.status= #{status}

order by t.create_time desc

    limit #{page}, #{row}

